// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {FHE, euint64} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";
import {ERC7984} from "@openzeppelin/confidential-contracts/token/ERC7984/ERC7984.sol";

/// @notice A faucet-mintable confidential token, so the demo has something to deposit.
///
/// @dev The pool takes any `IERC7984`; this is a constructor argument, not a dependency. If an
///      official cUSDT lands on Sepolia, point the pool at it and this contract goes away. The
///      mint is deliberately permissionless and rate-limited per address rather than owner-gated:
///      a judge should be able to try the product without asking anyone for tokens.
///
///      Not for any network where the balances mean something.
contract ConfidentialUSDT is ERC7984, ZamaEthereumConfig {
    /// @dev 1,000 tokens at 6 decimals. Enough to demonstrate, too little to distort a pool.
    uint64 public constant FAUCET_AMOUNT = 1_000_000_000;

    /// @dev One claim per address per period. Long enough to deter scripted draining, short
    ///      enough that a judge retrying an hour later is not blocked.
    uint32 public constant FAUCET_COOLDOWN = 1 hours;

    mapping(address account => uint256 timestamp) public lastClaimed;

    error FaucetCooldown(uint256 availableAt);

    event FaucetClaimed(address indexed account);

    /// @inheritdoc ERC7984
    function decimals() public pure override returns (uint8) {
        return 6;
    }

    constructor() ERC7984("Confidential USDT (demo)", "cUSDT", "") {}

    /// @notice Mint the caller a fixed amount of demo tokens.
    function claim() external {
        uint256 availableAt = lastClaimed[msg.sender] + FAUCET_COOLDOWN;
        if (lastClaimed[msg.sender] != 0 && block.timestamp < availableAt) {
            revert FaucetCooldown(availableAt);
        }
        lastClaimed[msg.sender] = block.timestamp;

        euint64 amount = FHE.asEuint64(FAUCET_AMOUNT);
        FHE.allowThis(amount);
        _mint(msg.sender, amount);

        emit FaucetClaimed(msg.sender);
    }

    /// @notice When the caller may claim again. Zero means now.
    function claimableAt(address account) external view returns (uint256) {
        if (lastClaimed[account] == 0) return 0;
        return lastClaimed[account] + FAUCET_COOLDOWN;
    }
}

contracts/mocks/WeightTreeHarness.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {FHE, ebool, euint8, euint32, euint64, euint128} from "@fhevm/solidity/lib/FHE.sol";

import {WeightTree} from "../WeightTree.sol";

/// @notice Test-only access to the tree's internals.
///
/// @dev The integral is the one piece of arithmetic in Ticket that cannot be eyeballed, because
///      it is encrypted at every step. This exists so a test can drive it directly and compare it
///      against a cleartext model, node by node, without the token or the draw in the way.
///
///      Amounts arrive in the clear here on purpose: `TicketPool` already covers the encrypted
///      input path, and what is under test is the accumulation, not the plumbing.
contract WeightTreeHarness is WeightTree {
    uint32 public immutable genesis;
    uint32 public immutable periodLength;

    euint64 public sealedWeight;

    /// @dev Bench-only scratch space for one level of the draw descent.
    uint32 private constant MAX_ARITY = 32;
    euint64[MAX_ARITY] private _children;
    euint8 public pickedIndex;

    constructor(uint32 arity_, uint32 capacity_, uint32 periodLength_) WeightTree(arity_, capacity_) {
        periodLength = periodLength_;
        genesis = uint32(block.timestamp);
    }

    function currentPeriod() public view returns (uint32) {
        return (uint32(block.timestamp) - genesis) / periodLength;
    }

    function periodStart(uint32 period) public view returns (uint32) {
        return genesis + period * periodLength;
    }

    function update(uint32 slot, uint64 amount, bool subtract) external {
        euint64 delta = FHE.asEuint64(amount);
        FHE.allowThis(delta);

        uint32 period = currentPeriod();
        _update(slot, delta, subtract, uint32(block.timestamp), period, periodStart(period));
    }

    /// @notice Seal a node at the current block time and hand the result to the caller.
    function seal(uint32 node) external {
        uint32 period = currentPeriod();
        sealedWeight = _sealed(node, uint32(block.timestamp), period, periodStart(period));
        FHE.allow(sealedWeight, msg.sender);
    }

    // ------------------------------------------------------- one draw level

    /// @notice Transaction one of a level: seal every child of `node` against real tree state.
    ///
    /// @dev Split from the pick because sealing is `k` independent chains while picking is one
    ///      long one, and the per-transaction ceiling that bites is sequential depth, not total
    ///      work. Splitting hands the whole depth budget to the half that needs it.
    function benchSealChildren(uint32 node) external {
        uint32 period = currentPeriod();
        uint32 start = periodStart(period);
        uint32 t = uint32(block.timestamp);

        for (uint32 j = 0; j < arity; j++) {
            _children[j] = _sealed(childOf(node, j), t, period, start);
        }
    }

    /// @notice Transaction two of a level: pick one child in proportion to its sealed weight.
    ///
    /// @dev The prefix sums come from a Hillis-Steele scan rather than a running total. A running
    ///      total is `k - 1` additions deep and blows the sequential-depth ceiling at k=16; the
    ///      scan is log2(k) deep for k*log2(k) additions, trading total work, which is slack, for
    ///      depth, which is not.
    ///
    ///      The comparison is cross-multiplied. `FHE.randEuint32` is uniform over exactly 2^32, so
    ///      testing `r * total < prefix_j * 2^32` picks a child in proportion to its weight without
    ///      dividing by an encrypted total and without rejection sampling — rejection would leak a
    ///      bit about the pool's size every time it retried.
    function benchSelectChild() external {
        uint32 k = arity;

        euint64[] memory scan = new euint64[](k);
        for (uint32 i = 0; i < k; i++) {
            scan[i] = _children[i];
        }
        for (uint32 d = 1; d < k; d <<= 1) {
            euint64[] memory next = new euint64[](k);
            for (uint32 i = 0; i < k; i++) {
                next[i] = i >= d ? FHE.add(scan[i], scan[i - d]) : scan[i];
            }
            scan = next;
        }

        euint128[] memory prefix = new euint128[](k);
        for (uint32 i = 0; i < k; i++) {
            prefix[i] = FHE.asEuint128(scan[i]);
        }

        euint32 r = FHE.randEuint32();
        euint128 point = FHE.mul(FHE.asEuint128(FHE.asEuint64(r)), prefix[k - 1]);

        euint8 idx = FHE.asEuint8(0);
        for (uint32 i = 0; i + 1 < k; i++) {
            ebool passed = FHE.ge(point, FHE.shl(prefix[i], uint8(32)));
            idx = FHE.add(idx, FHE.asEuint8(passed));
        }

        pickedIndex = idx;
        FHE.allowThis(pickedIndex);
        FHE.makePubliclyDecryptable(pickedIndex);
    }
}

contracts/spike/HcuProbe.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {FHE, ebool, euint8, euint32, euint64, euint128} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";

/// @notice Spike only. Measures what one level of the draw descent costs, per arity, so the
///         tree arity is chosen from a measurement instead of from arithmetic on the docs.
/// @dev The level is split into two transactions on purpose. The ceiling that binds is the
///      per-transaction *sequential depth* one, and depth accumulates along the dependency
///      chain seal -> prefix -> multiply -> compare. Splitting the level resets it.
contract HcuProbe is ZamaEthereumConfig {
    uint8 public constant MAX_K = 32;

    euint64[MAX_K] private _a;
    euint64[MAX_K] private _b;
    euint64[MAX_K] private _c;
    euint64[MAX_K] private _sealedWeight;

    euint8 public index;

    /// @notice Seed k children with trivially-encrypted aggregates. Setup, not measured.
    function seed(uint8 k) external {
        for (uint8 i = 0; i < k; i++) {
            _a[i] = FHE.asEuint64(uint64(1_000 + i));
            _b[i] = FHE.asEuint64(uint64(100 + i));
            _c[i] = FHE.asEuint64(uint64(10 + i));
            FHE.allowThis(_a[i]);
            FHE.allowThis(_b[i]);
            FHE.allowThis(_c[i]);
        }
    }

    /// @notice One level, in a single transaction. Kept to show where the ceiling bites.
    function probeLevel(uint8 k, uint64 T) external {
        _seal(k, T);
        _select(k);
    }

    /// @notice Transaction one of a split level: seal every child at time T. k independent
    ///         chains, each three operations deep.
    function sealChildren(uint8 k, uint64 T) external {
        _seal(k, T);
    }

    /// @notice Transaction two of a split level: prefix-sum the sealed children, draw the
    ///         point, count how many boundaries it passed. Depth starts fresh here.
    function selectChild(uint8 k) external {
        _select(k);
    }

    /// @notice Same step, but the prefix sums come from a Hillis-Steele scan: log2(k) deep
    ///         instead of k deep, at the cost of k*log2(k) operations instead of k.
    function selectChildScan(uint8 k) external {
        _selectScan(k);
    }

    function _seal(uint8 k, uint64 T) private {
        for (uint8 i = 0; i < k; i++) {
            _sealedWeight[i] = FHE.sub(FHE.add(_a[i], FHE.mul(_b[i], T)), _c[i]);
            FHE.allowThis(_sealedWeight[i]);
        }
    }

    function _selectScan(uint8 k) private {
        euint64[] memory scan = new euint64[](k);
        for (uint8 i = 0; i < k; i++) {
            scan[i] = _sealedWeight[i];
        }

        // Inclusive scan, log2(k) rounds deep.
        for (uint8 d = 1; d < k; d <<= 1) {
            euint64[] memory next = new euint64[](k);
            for (uint8 i = 0; i < k; i++) {
                next[i] = i >= d ? FHE.add(scan[i], scan[i - d]) : scan[i];
            }
            scan = next;
        }

        euint128[] memory prefix = new euint128[](k);
        for (uint8 i = 0; i < k; i++) {
            prefix[i] = FHE.asEuint128(scan[i]);
        }

        _pick(k, prefix);
    }

    function _select(uint8 k) private {
        euint128[] memory prefix = new euint128[](k);

        euint64 running = _sealedWeight[0];
        prefix[0] = FHE.asEuint128(running);
        for (uint8 i = 1; i < k; i++) {
            running = FHE.add(running, _sealedWeight[i]);
            prefix[i] = FHE.asEuint128(running);
        }

        _pick(k, prefix);
    }

    function _pick(uint8 k, euint128[] memory prefix) private {
        // The one euint128 multiply in the whole draw: r * total.
        euint32 r = FHE.randEuint32();
        euint128 product = FHE.mul(FHE.asEuint128(FHE.asEuint64(r)), prefix[k - 1]);

        // Cross-multiplied comparisons: how many prefix boundaries the point has passed.
        euint8 idx = FHE.asEuint8(0);
        for (uint8 i = 0; i + 1 < k; i++) {
            ebool passed = FHE.ge(product, FHE.shl(prefix[i], uint8(32)));
            idx = FHE.add(idx, FHE.asEuint8(passed));
        }

        index = idx;
        FHE.allowThis(index);
        FHE.makePubliclyDecryptable(index);
    }
}

contracts/spike/RoundTrip.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {FHE, euint64, externalEuint64} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";

/// @notice Spike only. Proves the three round trips Ticket depends on:
///         encrypted input in, user decryption out, and public decryption verified on chain.
/// @dev Not part of the product. Deleted once the pool carries these paths itself.
contract RoundTrip is ZamaEthereumConfig {
    euint64 private _value;
    euint64 private _second;

    uint64 public revealed;
    bool public finalized;
    bool public pairFinalized;

    error AlreadyFinalized();

    /// @notice Store an encrypted value and grant the sender the right to decrypt it.
    function store(externalEuint64 input, bytes calldata inputProof) external {
        _value = FHE.fromExternal(input, inputProof);
        FHE.allowThis(_value);
        FHE.allow(_value, msg.sender);
    }

    /// @notice The handle, for a user decryption under EIP-712.
    function value() external view returns (euint64) {
        return _value;
    }

    /// @notice Mark the value publicly decryptable. Irreversible, which is why the product
    ///         only ever does this to a draw step index.
    function publish() external {
        FHE.makePubliclyDecryptable(_value);
    }

    /// @notice Two publicly decryptable values, so the ordering of the handle array is
    ///         observable. The draw descent submits several handles at once and its safety
    ///         rests on the proof being bound to their order.
    function publishPair(externalEuint64 a, externalEuint64 b, bytes calldata inputProof) external {
        _value = FHE.fromExternal(a, inputProof);
        _second = FHE.fromExternal(b, inputProof);
        FHE.allowThis(_value);
        FHE.allowThis(_second);
        FHE.makePubliclyDecryptable(_value);
        FHE.makePubliclyDecryptable(_second);
    }

    /// @notice Both handles, in the order the proof must carry them.
    function pair() external view returns (euint64, euint64) {
        return (_value, _second);
    }

    /// @notice Accepts the pair only if the handles arrive in the order they were signed in.
    function finalizePair(bytes32[] calldata handles, uint64 a, uint64 b, bytes calldata decryptionProof) external {
        FHE.checkSignatures(handles, abi.encode(a, b), decryptionProof);
        pairFinalized = true;
    }

    /// @notice Accept a KMS-signed public decryption. Reverts on a forged or reordered proof.
    function finalize(bytes32[] calldata handles, uint64 cleartext, bytes calldata decryptionProof) external {
        if (finalized) revert AlreadyFinalized();
        FHE.checkSignatures(handles, abi.encode(cleartext), decryptionProof);
        revealed = cleartext;
        finalized = true;
    }
}

contracts/TicketPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {FHE, euint64, externalEuint64} from "@fhevm/solidity/lib/FHE.sol";
import {IERC7984} from "@openzeppelin/confidential-contracts/interfaces/IERC7984.sol";

import {Limits} from "./Limits.sol";
import {WeightTree} from "./WeightTree.sol";

/// @notice Deposits and withdrawals over the encrypted weight tree.
///
/// @dev Principal is never at risk here and never earns a discount: a withdrawal returns exactly
///      what was put in, and the only thing a deposit buys is time-weighted odds. The draw itself
///      lives in `DrawMachine`; this contract owns the money and the tree.
///
///      The token is a constructor argument typed as `IERC7984`, so the demo's faucet token and a
///      real confidential USDT are the same deployment with a different address.
contract TicketPool is WeightTree {
    /// @notice The confidential asset depositors hold.
    IERC7984 public immutable token;

    /// @notice When period 0 began.
    uint32 public immutable genesis;

    /// @notice Seconds per draw period.
    uint32 public immutable periodLength;

    /// @notice Slot 0 is a real slot, so occupancy is tracked separately rather than by `slot != 0`.
    mapping(address depositor => uint32 slot) private _slotOf;
    mapping(address depositor => bool assigned) private _hasSlot;
    mapping(uint32 slot => address depositor) public depositorAt;

    /// @notice Slots are assigned once and never reused, so this only ever climbs.
    uint32 public nextSlot;

    /// @notice An interaction that arrived while a draw held the tree still, waiting to be
    ///         executed the moment the draw settles.
    ///
    /// @dev `payTo` is zero for a deposit — the token already moved when it was queued — and the
    ///      depositor for a withdrawal, whose token movement is what is being deferred.
    struct Pending {
        uint32 slot;
        bool subtract;
        address payTo;
        euint64 amount;
    }

    /// @notice The cap on interactions parked behind one draw. A draw is eight transactions and
    ///         well under a minute, so this is a very deep queue in practice.
    uint256 internal constant MAX_QUEUE = 32;

    /// @notice Parked interactions executed per transaction.
    ///
    /// @dev Each one is a full leaf-to-root walk — the benchmark prices it at roughly half a
    ///      million gas — so draining a full queue inside `settle` would need thirty million and
    ///      no block would take it. The drain is paged instead: `settle` does the first page and
    ///      anyone may push the rest through. Settling is not allowed to depend on how many
    ///      people happened to act while the draw was running.
    uint256 internal constant DRAIN_PER_TX = 4;

    Pending[] private _queue;

    /// @dev Read index into `_queue`. The array is cleared once it is fully drained rather than
    ///      element by element, so this is what says where the drain has got to.
    uint256 private _drained;

    mapping(uint32 slot => bool queued) private _slotQueued;

    error PoolFull();
    error NoSlot(address account);
    error PeriodTooLong(uint32 periodLength);
    error PeriodZero();
    error QueueFull();
    error AlreadyQueued(uint32 slot);
    error QueueNotDrained(uint256 remaining);

    event SlotAssigned(address indexed depositor, uint32 indexed slot);
    event Deposited(address indexed depositor, uint32 indexed slot);
    event Withdrawn(address indexed depositor, uint32 indexed slot);
    event Queued(address indexed depositor, uint32 indexed slot, bool subtract, uint256 position);
    event QueueDrained(uint256 count);

    constructor(
        IERC7984 token_,
        uint32 arity_,
        uint32 capacity_,
        uint32 periodLength_
    ) WeightTree(arity_, capacity_) {
        if (periodLength_ == 0) revert PeriodZero();
        if (periodLength_ > Limits.MAX_PERIOD) revert PeriodTooLong(periodLength_);

        token = token_;
        periodLength = periodLength_;
        genesis = uint32(block.timestamp);
    }

    // ---------------------------------------------------------------- periods

    /// @notice The period `block.timestamp` falls in.
    function currentPeriod() public view returns (uint32) {
        return (uint32(block.timestamp) - genesis) / periodLength;
    }

    /// @notice When a period began.
    function periodStart(uint32 period) public view returns (uint32) {
        return genesis + period * periodLength;
    }

    // ------------------------------------------------------------------ slots

    /// @notice The caller's slot, and whether they have one at all.
    function slotOf(address account) public view returns (uint32 slot, bool assigned) {
        return (_slotOf[account], _hasSlot[account]);
    }

    /// @notice Depositors who have ever deposited. The draw descends over `capacity` leaves
    ///         regardless, so this is a UX number, not a cost.
    function participantCount() external view returns (uint32) {
        return nextSlot;
    }

    function _slotFor(address account) private returns (uint32) {
        if (_hasSlot[account]) return _slotOf[account];
        if (nextSlot >= capacity) revert PoolFull();

        uint32 slot = nextSlot++;
        _slotOf[account] = slot;
        _hasSlot[account] = true;
        depositorAt[slot] = account;

        emit SlotAssigned(account, slot);
        return slot;
    }

    // --------------------------------------------------------------- deposits

    /// @notice Deposit an encrypted amount. The caller must have made this contract an operator
    ///         on the token first.
    ///
    /// @dev The amount is clamped twice and neither clamp can revert, because reverting on an
    ///      encrypted comparison would leak the comparison. `FHE.min` caps it at `MAX_DEPOSIT` so
    ///      the aggregates cannot overflow, and the token itself caps it at the sender's balance
    ///      and returns what actually moved. That return value, not the request, is what enters
    ///      the tree — otherwise a depositor could claim odds on money they never sent.
    function deposit(externalEuint64 encryptedAmount, bytes calldata inputProof) external {
        uint32 slot = _slotFor(msg.sender);

        euint64 requested = FHE.fromExternal(encryptedAmount, inputProof);
        euint64 capped = FHE.min(requested, FHE.asEuint64(Limits.MAX_DEPOSIT));
        FHE.allowTransient(capped, address(token));

        euint64 transferred = token.confidentialTransferFrom(msg.sender, address(this), capped);
        FHE.allowThis(transferred);

        _applyOrQueue(slot, transferred, false, address(0));
        _grantLeaf(slot, msg.sender);

        emit Deposited(msg.sender, slot);
    }

    // ------------------------------------------------------------ withdrawals

    /// @notice Withdraw an encrypted amount, clamped to the caller's balance.
    ///
    /// @dev Asking for more than you hold is not an error and must not be one: an error is a
    ///      public signal about a private balance. The request is silently clamped, which is both
    ///      the safe behaviour and the honest one — you cannot underflow the tree by guessing.
    function withdraw(externalEuint64 encryptedAmount, bytes calldata inputProof) external {
        uint32 slot = _requireSlot(msg.sender);
        euint64 requested = FHE.fromExternal(encryptedAmount, inputProof);
        (euint64 balance, ) = _balanceOf(slot);
        _exit(slot, FHE.min(requested, balance));
    }

    /// @notice Withdraw the caller's entire principal.
    function withdrawAll() external {
        uint32 slot = _requireSlot(msg.sender);
        (euint64 balance, ) = _balanceOf(slot);
        _exit(slot, balance);
    }

    function _exit(uint32 slot, euint64 amount) private {
        FHE.allowThis(amount);
        _applyOrQueue(slot, amount, true, msg.sender);
        _grantLeaf(slot, msg.sender);

        emit Withdrawn(msg.sender, slot);
    }

    // ---------------------------------------------------------------- queueing

    /// @notice Whether a draw is currently holding the tree still. Always false here; the draw
    ///         machine that inherits this contract is what makes it true.
    function drawInFlight() public view virtual returns (bool) {
        return false;
    }

    /// @notice How many interactions are still waiting to be executed.
    function queueLength() public view returns (uint256) {
        return _queue.length - _drained;
    }

    /// @dev A draw is judged against the tree as it stood at its seal time, so the tree cannot
    ///      move while one is in flight. Blocking withdrawals for that window would breach the
    ///      promise that money is available at any time — the whole reason prize-linked saving is
    ///      not gambling — so interactions are parked instead and executed automatically when the
    ///      draw settles. The depositor acts once and the transaction lands without them.
    ///
    ///      One parked interaction per slot. A second withdrawal would clamp against a balance the
    ///      first has not yet spent, and two of them together could ask for more than the leaf
    ///      holds. The bound is on the slot, which is public, so refusing leaks nothing.
    function _applyOrQueue(uint32 slot, euint64 amount, bool subtract, address payTo) internal {
        if (!drawInFlight()) {
            _execute(slot, amount, subtract, payTo);
            return;
        }

        if (queueLength() >= MAX_QUEUE) revert QueueFull();
        if (_slotQueued[slot]) revert AlreadyQueued(slot);

        _slotQueued[slot] = true;
        _queue.push(Pending({slot: slot, subtract: subtract, payTo: payTo, amount: amount}));

        emit Queued(msg.sender, slot, subtract, _queue.length - 1);
    }

    /// @notice Execute up to `max` parked interactions, in arrival order.
    ///
    /// @dev Permissionless on purpose. A parked withdrawal is somebody's money, and whether they
    ///      get it back must not depend on a keeper choosing to finish its work.
    function drainQueue(uint256 max) public returns (uint256 executed) {
        uint256 end = _queue.length;
        uint256 i = _drained;
        uint256 stop = i + max;
        if (stop > end) stop = end;

        for (; i < stop; i++) {
            Pending memory p = _queue[i];
            _slotQueued[p.slot] = false;
            _execute(p.slot, p.amount, p.subtract, p.payTo);
            executed++;
        }

        _drained = i;
        if (i == end && end != 0) {
            delete _queue;
            _drained = 0;
        }

        emit QueueDrained(executed);
    }

    /// @dev One page, inside `settle`.
    function _drainQueue() internal {
        drainQueue(DRAIN_PER_TX);
    }

    /// @dev The leaf is re-granted to its owner on every execution, not only on the call that
    ///      queued it. `_update` replaces the ciphertexts it touches, and a handle nobody is
    ///      allowed to decrypt is a balance its owner has lost sight of — the grant has to follow
    ///      the write, wherever the write happens.
    function _execute(uint32 slot, euint64 amount, bool subtract, address payTo) private {
        uint32 period = currentPeriod();
        _update(slot, amount, subtract, uint32(block.timestamp), period, periodStart(period));
        _grantLeaf(slot, depositorAt[slot]);

        if (payTo != address(0)) {
            FHE.allowTransient(amount, address(token));
            token.confidentialTransfer(payTo, amount);
        }
    }

    function _requireSlot(address account) private view returns (uint32) {
        if (!_hasSlot[account]) revert NoSlot(account);
        return _slotOf[account];
    }

    // -------------------------------------------------------------- balances

    function _balanceOf(uint32 slot) private view returns (euint64 balance, euint64 accrued) {
        (euint64 a, euint64 b, , ) = _leaf(slot);
        return (b, a);
    }

    /// @notice The caller's principal, as a handle they are allowed to decrypt.
    function confidentialBalanceOf(address account) external view returns (euint64) {
        (euint64 balance, ) = _balanceOf(_slotOf[account]);
        return balance;
    }

    /// @notice The integral accrued so far this period, up to the last time this leaf moved.
    ///
    /// @dev Paired with `lastMoved`, this is everything the owner needs: the live weight is
    ///      `accrued + balance * (now - lastMoved)`, and the elapsed term is public, so the owner
    ///      finishes the calculation off chain after decrypting two handles.
    function confidentialWeightOf(address account) external view returns (euint64) {
        (, euint64 accrued) = _balanceOf(_slotOf[account]);
        return accrued;
    }

    /// @notice When this depositor's leaf last moved, and in which period.
    function lastMoved(address account) external view returns (uint32 at, uint32 period) {
        (, , uint32 lastUpdate, uint32 lastPeriod) = _leaf(_slotOf[account]);
        return (lastUpdate, lastPeriod);
    }
}

contracts/WeightTree.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {FHE, euint64} from "@fhevm/solidity/lib/FHE.sol";
import {ZamaEthereumConfig} from "@fhevm/solidity/config/ZamaConfig.sol";

import {Limits} from "./Limits.sol";

/// @notice The core of Ticket: odds that are time-weighted, encrypted, and still summable.
///
/// @dev Odds cannot be "balance at draw time" — depositing a moment before the draw and leaving a
///      moment after would be free money, and it is the exploit the whole design exists to close.
///      So the quantity that decides a draw is the *integral of balance over the period*, and it
///      has to be maintained under encryption, where you cannot look at a number to decide what to
///      do next.
///
///      Each node keeps two ciphertexts and two plaintext timestamps:
///
///        A  accumulated integral for the current period, up to `lastUpdate`
///        B  current total balance in this subtree
///
///      and the weight at any later time T is
///
///        weight(T) = A + B * (T - lastUpdate)
///
///      The multiplier is a *plaintext* elapsed time, so this is a ciphertext-by-scalar multiply —
///      one of the cheap operations — not the ciphertext-by-ciphertext multiply that would blow the
///      per-transaction compute budget. Nothing about the balance is revealed by knowing how long
///      it sat there.
///
///      `B` is additive across children by construction, and `A` is the integral of `B`, so a
///      parent's pair is exactly the subtree's pair provided every change folds the whole path to
///      the root before touching a balance. `_update` does that, which is why it walks upward.
///      That is what makes the draw a descent over `depth` levels instead of a scan over `N`
///      depositors.
///
///      Periods reset lazily. A node whose `lastPeriod` is stale has, by definition, an integral of
///      zero for the current period; there is no O(N) reset pass, and there does not need to be.
abstract contract WeightTree is ZamaEthereumConfig {
    struct Node {
        euint64 A;
        euint64 B;
        uint32 lastUpdate;
        uint32 lastPeriod;
    }

    /// @notice Children per node.
    uint32 public immutable arity;

    /// @notice Leaves, and therefore the maximum number of depositors.
    uint32 public immutable capacity;

    /// @notice Levels between the root and a leaf. The number of steps a draw takes.
    uint8 public immutable treeDepth;

    /// @notice Index of the leaf holding slot 0.
    uint32 public immutable leafOffset;

    mapping(uint32 index => Node node) internal _nodes;

    error ArityOutOfRange(uint32 arity);
    error CapacityNotAPowerOfArity(uint32 capacity, uint32 arity);
    error CapacityTooLarge(uint32 capacity);

    /// @param arity_ children per node
    /// @param capacity_ leaf count, which must be an exact power of `arity_`
    constructor(uint32 arity_, uint32 capacity_) {
        if (arity_ < 2 || arity_ > 32) revert ArityOutOfRange(arity_);
        if (capacity_ > Limits.MAX_SLOTS) revert CapacityTooLarge(capacity_);

        // Walk the powers of the arity rather than trusting a log. `internalNodes` accumulates
        // (k^d - 1) / (k - 1) on the way, which is the index the leaves start at.
        uint32 size = 1;
        uint32 internalNodes = 0;
        uint8 d = 0;
        while (size < capacity_) {
            internalNodes += size;
            size *= arity_;
            d += 1;
        }
        if (size != capacity_) revert CapacityNotAPowerOfArity(capacity_, arity_);

        arity = arity_;
        capacity = capacity_;
        treeDepth = d;
        leafOffset = internalNodes;
    }

    /// @notice Index of node `n`'s `j`-th child.
    function childOf(uint32 n, uint32 j) public view returns (uint32) {
        return n * arity + 1 + j;
    }

    /// @notice Index of node `n`'s parent. Undefined at the root.
    function parentOf(uint32 n) public view returns (uint32) {
        return (n - 1) / arity;
    }

    /// @notice The weight of a subtree at time `T`, without writing anything.
    ///
    /// @dev The period branch is on plaintext, not on a ciphertext: whether a node is stale is a
    ///      property of block timestamps, which are public anyway. A stale node contributes only
    ///      the balance it carried into the period.
    function _sealed(uint32 n, uint32 T, uint32 period, uint32 periodStart) internal returns (euint64) {
        Node storage node = _nodes[n];

        euint64 weight;
        if (node.lastPeriod != period) {
            weight = FHE.mul(node.B, uint64(T - periodStart));
        } else {
            weight = FHE.add(node.A, FHE.mul(node.B, uint64(T - node.lastUpdate)));
        }

        FHE.allowThis(weight);
        return weight;
    }

    /// @notice Move a node into the current period, discarding the previous period's integral.
    ///
    /// @dev Odds are per-period, so last period's integral is not merely stale, it is wrong. The
    ///      balance carries over; the integral does not.
    function _roll(uint32 n, uint32 period, uint32 periodStart) internal {
        Node storage node = _nodes[n];
        if (node.lastPeriod == period) return;

        node.A = FHE.asEuint64(0);
        node.lastUpdate = periodStart;
        node.lastPeriod = period;
        FHE.allowThis(node.A);
    }

    /// @notice Fold elapsed time into the integral, bringing `A` current as of `t`.
    function _fold(uint32 n, uint32 t) internal {
        Node storage node = _nodes[n];
        uint32 elapsed = t - node.lastUpdate;
        if (elapsed == 0) return;

        node.A = FHE.add(node.A, FHE.mul(node.B, uint64(elapsed)));
        node.lastUpdate = t;
        FHE.allowThis(node.A);
    }

    /// @notice Let `owner` decrypt their own leaf, and nothing above it.
    ///
    /// @dev A leaf is one depositor, so granting it discloses only what that depositor already
    ///      knows. Internal nodes are sums over other people and are never granted to anyone —
    ///      the contract holds them and the KMS decrypts exactly one of them per draw level.
    ///
    ///      Both halves are granted because the weight is `A + B * (T - lastUpdate)` and the
    ///      elapsed term is plaintext: the owner decrypts two numbers and finishes the arithmetic
    ///      in the clear, which costs the chain nothing.
    function _grantLeaf(uint32 slot, address owner) internal {
        Node storage node = _nodes[leafOffset + slot];
        FHE.allow(node.A, owner);
        FHE.allow(node.B, owner);
    }

    /// @notice A leaf's stored halves, for the owner to decrypt.
    function _leaf(uint32 slot) internal view returns (euint64 a, euint64 b, uint32 lastUpdate, uint32 lastPeriod) {
        Node storage node = _nodes[leafOffset + slot];
        return (node.A, node.B, node.lastUpdate, node.lastPeriod);
    }

    /// @notice Apply a balance change at `slot` and carry it to the root.
    ///
    /// @dev Every node on the path is folded *before* its balance moves, which is what keeps `A`
    ///      the true integral of `B` at every level. Off-path nodes are untouched and stay correct
    ///      on their own terms — their balance did not change, so neither did their integral.
    ///
    /// @param slot the depositor's leaf
    /// @param delta the amount, already clamped to `Limits.MAX_DEPOSIT`
    /// @param subtract true for a withdrawal
    function _update(
        uint32 slot,
        euint64 delta,
        bool subtract,
        uint32 t,
        uint32 period,
        uint32 periodStart
    ) internal {
        uint32 n = leafOffset + slot;

        while (true) {
            _roll(n, period, periodStart);
            _fold(n, t);

            Node storage node = _nodes[n];
            node.B = subtract ? FHE.sub(node.B, delta) : FHE.add(node.B, delta);
            FHE.allowThis(node.B);

            if (n == 0) break;
            n = parentOf(n);
        }
    }
}

